package dev.metallicarts.config;

import com.google.gson.*;
import net.fabricmc.loader.api.FabricLoader;
import java.nio.file.*;
import java.util.*;

/** Validated server balance policy. Fixed saved-data unit definitions are deliberately not reinterpreted. */
public record AdvancedConfig(int schema,Detection detection,Emotions emotions,Time time,Body body,Enhancement enhancement,Social social,Compounding compounding,Constructs constructs){
 public record Detection(int interval,int pulseLifetime,double range,boolean sound){public Detection{AdvancedConfig.checkRange(range,4,64);integer(interval,1,100);integer(pulseLifetime,interval,200);}}
 public record Emotions(double rate,double frameCap,double recovery,double range){public Emotions{AdvancedConfig.checkRange(rate,.00001,.1);AdvancedConfig.checkRange(frameCap,rate,.25);AdvancedConfig.checkRange(recovery,.000001,.1);AdvancedConfig.checkRange(range,2,32);}}
 public record Time(double minimum,double maximum,double baseRadius,double maximumRadius,double speedFactor,double slowFactor,double boundaryDegrees,List<String> machines){public Time{AdvancedConfig.checkRange(minimum,.1,1);AdvancedConfig.checkRange(maximum,1,8);AdvancedConfig.checkRange(baseRadius,2,12);AdvancedConfig.checkRange(maximumRadius,baseRadius,24);AdvancedConfig.checkRange(speedFactor,.1,8);AdvancedConfig.checkRange(slowFactor,.1,16);AdvancedConfig.checkRange(boundaryDegrees,0,30);machines=List.copyOf(machines);if(machines.size()>128||machines.stream().anyMatch(s->!s.matches("[a-z0-9_.-]+:[a-z0-9_/.-]+")))throw new IllegalArgumentException("Invalid temporal machine list");}}
 public record Body(long awakeFatigue,long sleepRecovery,long thermalStep,long emergencyCost,long cureCost,int emergencyCooldown,int opportunityProbes,int opportunityRadius){public Body{longRange(awakeFatigue,1,100000);longRange(sleepRecovery,1,10000000);longRange(thermalStep,1,100000);longRange(emergencyCost,1000,1000000000);longRange(cureCost,1000,emergencyCost);integer(emergencyCooldown,20,72000);integer(opportunityProbes,1,4096);integer(opportunityRadius,2,24);}}
 public record Enhancement(int contactCooldown,double maximumBoost,double maximumPower,long massScale,long dodgeCost,int dodgeCooldown){public Enhancement{integer(contactCooldown,1,200);AdvancedConfig.checkRange(maximumBoost,1,32);AdvancedConfig.checkRange(maximumPower,1,1000);longRange(massScale,1,1000000000);longRange(dodgeCost,1,1000000000);integer(dodgeCooldown,2,200);}}
 public record Social(double tradeCoefficient,double maximumDiscount,double maximumSurcharge,double familiarityBonus){public Social{AdvancedConfig.checkRange(tradeCoefficient,0,.5);AdvancedConfig.checkRange(maximumDiscount,0,.8);AdvancedConfig.checkRange(maximumSurcharge,0,2);AdvancedConfig.checkRange(familiarityBonus,0,2);}}
 public record Compounding(boolean enabled,int multiplier){public Compounding{integer(multiplier,2,100);}}
 public record Constructs(boolean enabled,boolean exceptionalExtraction,double nonlethalRetention,int controlTicks,double kolossMaximumScale,long kolossGrowthTicks,int kandraDegradeTicks,int preparationBones,int wolfBones,int slimeBones,int shapeMaterials,int unsealingRings){public Constructs{AdvancedConfig.checkRange(nonlethalRetention,.01,.5);integer(controlTicks,20,400);AdvancedConfig.checkRange(kolossMaximumScale,1.2,3);longRange(kolossGrowthTicks,1200,24000000);integer(kandraDegradeTicks,20,24000);integer(preparationBones,1,64);integer(wolfBones,1,64);integer(slimeBones,1,64);integer(shapeMaterials,1,64);integer(unsealingRings,1,16);}}
 public static final AdvancedConfig DEFAULT=new AdvancedConfig(1,new Detection(10,20,32,true),new Emotions(.003,.025,.0002,12),new Time(.25,4,5,8,2,3,5,List.of("minecraft:furnace","minecraft:blast_furnace","minecraft:smoker","minecraft:brewing_stand","metallicarts:metallurgy_table")),new Body(1000,500000,5000,200000,50000,1200,512,8),new Enhancement(20,8,32,1000,1000,10),new Social(.1,.4,.3,.25),new Compounding(true,10),new Constructs(true,false,.25,100,1.8,168000,200,2,8,4,2,1));
 private static final Gson GSON=new GsonBuilder().setPrettyPrinting().create();
 private static AdvancedConfig active=DEFAULT;
 public AdvancedConfig{if(schema!=1)throw new IllegalArgumentException("Unsupported advanced config");Objects.requireNonNull(detection);Objects.requireNonNull(emotions);Objects.requireNonNull(time);Objects.requireNonNull(body);Objects.requireNonNull(enhancement);Objects.requireNonNull(social);Objects.requireNonNull(compounding);Objects.requireNonNull(constructs);}
 private static void checkRange(double v,double min,double max){if(!Double.isFinite(v)||v<min||v>max)throw new IllegalArgumentException("Advanced balance value outside "+min+".."+max);}
 private static void integer(int v,int min,int max){AdvancedConfig.checkRange(v,min,max);}private static void longRange(long v,long min,long max){if(v<min||v>max)throw new IllegalArgumentException("Advanced integer balance value outside limits");}
 public static AdvancedConfig get(){return active;}
 public static void install(AdvancedConfig policy){active=Objects.requireNonNull(policy);}
 public static AdvancedConfig parse(String text){var json=JsonParser.parseString(text).getAsJsonObject();merge(json,GSON.toJsonTree(DEFAULT).getAsJsonObject());PolicyJson.validate(json,AdvancedConfig.class);return GSON.fromJson(json,AdvancedConfig.class);}
 private static void merge(JsonObject target,JsonObject defaults){for(var e:defaults.entrySet())if(!target.has(e.getKey()))target.add(e.getKey(),e.getValue().deepCopy());else if(e.getValue().isJsonObject()&&target.get(e.getKey()).isJsonObject())merge(target.getAsJsonObject(e.getKey()),e.getValue().getAsJsonObject());}
 public static void load(){var file=FabricLoader.getInstance().getConfigDir().resolve("metallicarts-advanced.json");try{if(!Files.exists(file)){Files.createDirectories(file.getParent());Files.writeString(file,GSON.toJson(DEFAULT),StandardOpenOption.CREATE_NEW);active=DEFAULT;}else {String original=Files.readString(file);var json=JsonParser.parseString(original).getAsJsonObject();var merged=json.deepCopy();merge(merged,GSON.toJsonTree(DEFAULT).getAsJsonObject());var candidate=parse(GSON.toJson(merged));if(!json.equals(merged)){var backup=file.resolveSibling("metallicarts-advanced.before-0.8.json");if(!Files.exists(backup))Files.copy(file,backup);Files.writeString(file,GSON.toJson(merged));}active=candidate;}}catch(Exception e){throw new IllegalStateException("Cannot load "+file,e);}}
}

